"""Render investigator reports from measured outputs and explicit assessments."""
import json, re
from pathlib import Path
from research_assessment import main as assessment_main, DIMENSIONS
ROOT=Path(__file__).resolve().parents[1]; REPO=ROOT.parent
def read(name):return json.loads((ROOT/name).read_text())
def write(name,text):
    if name.endswith('.md'):
        # Format prose without changing code or exact artifact/primary URLs.
        parts=re.split(r'(```[\s\S]*?```|`[^`\n]+`|\[[^\]\n]*\]\([^\n]*?\))',text)
        for i in range(0,len(parts),2):
            p=parts[i]
            p=re.sub(r'(?<=[a-uw-z’])(?=\d)', ' ', p)
            p=re.sub(r'\b(Qwen|Llama|OLMo|Gemma) (\d)',r'\1\2',p)
            p=re.sub(r'\bN(\d+)',r'N=\1',p)
            p=re.sub(r'\bSD(\d+)',r'SD \1',p)
            p=re.sub(r'\b(SD|SE|parameter|discordance)\.(\d)',r'\1 0.\2',p)
            p=re.sub(r'\b(at|and|of|to)\.(\d)',r'\1 0.\2',p)
            p=re.sub(r'(?<=\d)(questions|records|calls|files|successes|models|draws|agents|cases|attempts|groups|cells|tests|minutes|backbones|independent|unique|simulated)',r' \1',p)
            p=p.replace('CI[','CI [')
            parts[i]=p
        text=''.join(parts)
    (ROOT/name).write_text(text.strip()+'\n')
def link(path,label=None):return f'[{label or path}]({REPO/path})'
def pp(x):return f'{100*x:+.3f}'
def estimate(d):return f"{pp(d['mean'])} pp; exploratory paired bootstrap 95% CI [{pp(d['ci95'][0])}, {pp(d['ci95'][1])}], N={d['n']} unique questions"

